package com.stockpilot.repository;
import com.stockpilot.entity.Product; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*;
public interface ProductRepository extends JpaRepository<Product,Long>{ Optional<Product> findBySku(String sku); boolean existsBySku(String sku); List<Product> findByNameContainingIgnoreCaseOrSkuContainingIgnoreCase(String name,String sku); List<Product> findByQuantityLessThanEqual(int level); }